  private void Ensure(uint address,byte[] bytes,bool immutable){int i=0;while(i<bytes.Length){bool present=true;byte value=0;try{value=m.ReadByte(address+(uint)i);}catch(InvalidOperationException){present=false;}if(present){if(immutable&&value!=bytes[i])throw new InvalidDataException("Conflicting native binding");++i;continue;}int first=i;while(++i<bytes.Length){try{m.ReadByte(address+(uint)i);break;}catch(InvalidOperationException){}}var span=new byte[i-first];Array.Copy(bytes,first,span,0,span.Length);m.Map(address+(uint)first,span);}}
