  private string CString(uint address){return Encoding.ASCII.GetString(m.ReadBytes(address,m.StrLen(address)));}
  private int Compare(uint a,uint b,uint n){for(uint i=0;i<n;++i){int delta=m.ReadByte(a+i)-m.ReadByte(b+i);if(delta!=0)return delta;}return 0;}
  private void Error(uint address){throw new InvalidDataException("Original jurisdiction fault at CString "+address.ToString("x8"));}
